//! The SDK for Swift, Kotlin and Python: [`kassigner_sdk_host`] behind a
//! C ABI, the bindings generated by UniFFI. Each object wraps the host
//! crate's type, each record copies its fields, each function calls the
//! host's; every rule and check is the SDK's.
//!
//! Objects are handles the platform holds, records plain values. Bytes are
//! byte arrays, sompi and masses 64-bit, counts 32-bit. An error is a
//! [`Fault`] with the SDK's name for it (`Insufficient { have: 5, need: 7 }`)
//! or a short message. Objects with state ([`request::RequestBuilder`],
//! [`transport::Reader`], [`bundle::Hints`]) keep it behind a mutex, as a
//! platform may call them from any thread.

#![deny(unsafe_code)]

uniffi::setup_scaffolding!("kassigner_sdk");

pub mod bundle;
pub mod card;
pub mod message;
pub mod node;
pub mod reply;
pub mod request;
pub mod transport;
pub mod watch;

use std::sync::{Mutex, MutexGuard};

use kassigner_sdk_host as host;

/// Why a call failed, as the platform's error.
#[derive(Clone, Debug, PartialEq, Eq, uniffi::Error)]
#[uniffi(flat_error)]
pub enum Fault {
    /// The SDK refused, by this name.
    Sdk(String),
}

impl core::fmt::Display for Fault {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Fault::Sdk(s) => f.write_str(s),
        }
    }
}

impl std::error::Error for Fault {}

impl From<host::Fault> for Fault {
    fn from(f: host::Fault) -> Self {
        Fault::Sdk(f.0)
    }
}

/// The lock of an object with state, for one call. A lock a panic left
/// poisoned still gives its value: a builder changes by one push or
/// assignment, so it is whole.
pub(crate) fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {
    m.lock().unwrap_or_else(|e| e.into_inner())
}

/// What a unit accepts: the bounds a request is built within.
#[derive(Clone, Copy, Debug, PartialEq, Eq, uniffi::Object)]
pub struct Profile {
    inner: host::Profile,
}

#[uniffi::export]
impl Profile {
    /// The ESP32-S3 units' profile, which the P4 units share: the bounds
    /// their firmware declares.
    #[uniffi::constructor]
    pub fn esp32s3() -> Profile {
        Profile {
            inner: host::Profile::esp32s3(),
        }
    }

    pub fn max_inputs(&self) -> u32 {
        self.inner.max_inputs()
    }

    pub fn max_outputs(&self) -> u32 {
        self.inner.max_outputs()
    }

    pub fn max_frames(&self) -> u32 {
        self.inner.max_frames()
    }

    pub fn max_reassembled(&self) -> u32 {
        self.inner.max_reassembled()
    }

    pub fn max_sigs_per_input(&self) -> u32 {
        self.inner.max_sigs_per_input()
    }

    pub fn max_redeem(&self) -> u32 {
        self.inner.max_redeem()
    }
}

impl Profile {
    /// The host crate's profile.
    pub const fn inner(&self) -> &host::Profile {
        &self.inner
    }
}

/// A network's mass rates, which fees are paid over.
#[derive(Clone, Copy, Debug, PartialEq, Eq, uniffi::Object)]
pub struct Rates {
    inner: host::Rates,
}

#[uniffi::export]
impl Rates {
    /// Mainnet's rates.
    #[uniffi::constructor]
    pub fn mainnet() -> Rates {
        Rates {
            inner: host::Rates::mainnet(),
        }
    }
}

impl Rates {
    /// The host crate's rates.
    pub const fn inner(&self) -> &host::Rates {
        &self.inner
    }
}

/// This library's version: the SDK's release.
#[uniffi::export]
pub fn version() -> String {
    host::version()
}
